def digest(b):return hashlib.sha256(b).hexdigest()
def binding(path):
 p=Path(path);b=p.read_bytes();return {'path':p.as_posix(),'sha256':digest(b),'bytes':len(b)}
def load(p):return json.loads(Path(p).read_bytes())
def git(*args):return subprocess.check_output(['git','-C',str(REPO),*args],env={**os.environ,'GIT_OPTIONAL_LOCKS':'0','GIT_TERMINAL_PROMPT':'0'})
def bind3(x):return {k:x[k] for k in ['path','sha256','bytes']}
def verify_raw(x):
 b=x['utf8Raw'].encode('utf-8');assert digest(b)==x['sha256'] and len(b)==x['bytes'];return b
def ptr(o,p):
 assert p=='' or p.startswith('/')
 for part in p[1:].split('/') if p else []:
  part=part.replace('~1','/').replace('~0','~');o=o[int(part)] if isinstance(o,list) else o[part]
 return o
def run():
 assert Path(sys.executable).as_posix().lower()=='f:/chnobelruntime/venv/scripts/python.exe'
 for k in ['TEMP','TMP','TMPDIR']:assert Path(os.environ[k]).as_posix()=='F:/ChnobelRuntime/tmp'
 assert os.environ['UV_CACHE_DIR']=='F:/ChnobelRuntime/cache/uv'
 assert os.environ['PYTHONDONTWRITEBYTECODE']=='1' and os.environ['PYTHONIOENCODING']=='utf-8'
 assert git('rev-parse','HEAD').decode().strip()==BASE
 for n,h in FREEZE_PINS.items():assert binding(ROOT/n)['sha256']==h
 inp=load(ROOT/'input-bindings.json');pro=load(ROOT/'procedural-bindings.json')
 fixed_rows=inp['mandatoryFiles']+pro['proceduralSources']+[binding(ROOT/n) for n in FREEZE_PINS]
 fixed={x['path']:bind3(x) for x in fixed_rows};assert len(fixed_rows)==len(fixed)==69
 assert inp['mandatoryFileCount']==len(inp['mandatoryFiles'])==63
 for x in fixed.values():assert binding(x['path'])==x
 for x in pro['proceduralSources']:assert verify_raw(x)==Path(x['path']).read_bytes()
 mutable={x['path']:x for x in pro['mutableParentContextsAtDispatch']}
 for x in mutable.values():verify_raw(x)
 allowed=inp['parentWriteContract']['allowedParentRepositoryWritePaths'];assert len(allowed)==len(set(allowed))==21
 commit_paths=git('diff','--name-only',inp['parentBase'],BASE).decode().splitlines();assert set(commit_paths)==set(allowed)
 cache={}
 def original(source,pointer):
  assert source in fixed
  if source not in cache:cache[source]=load(source)
  return ptr(cache[source],pointer)
 result=[]
 for role,pins in PINS.items():
  folder=ROOT/role;assert {p.name for p in folder.iterdir()}==set(pins)
  files=[binding(folder/n) for n in pins]
  for f in files:assert f['sha256']==pins[Path(f['path']).name]
  s=load(folder/'sources.json');d=load(folder/'decision.json')
  assert s['role']==d['role']==role and s['scopeId']==d['scopeId']==inp['scopeId']=='GUARD-POLICY-01-WHOLE-TEXT'
  assert d['subject']==inp['proposal']==binding(inp['proposal']['path'])
  assert d['scopeStatus']=='COMPLETE' and d['wholeTextVote']=='JA' and d['unconditional'] is True
  assert d['conditions']==d['requiredTextChanges']==[]
  assert len(d['sections'])==7 and {x['id'] for x in d['sections']}=={'P'+str(i) for i in range(1,8)}
  assert all(x['status']=='PASS_TEXT' and x['reason'] and x['sourceLocations'] for x in d['sections'])
  for k in ['recommendationsAccepted','ratificationIssued','blockerClosed','implementationAuthorized']:assert d[k] is False
  assert d['wholeManifestVerdict']=='NOT_ISSUED'
  for obj in [s,d]:
   for k in ['product','parser','schema','evaluator','tests','native']:assert obj['execution'][k]=='NOT_RUN'
  assert len(s['records'])==69 and {x['path'] for x in s['records']}==set(fixed)
  for x in s['records']:
   assert x['before']==x['after']==x['frozen' if role=='didaktik' else 'freeze']==fixed[x['path']]
   assert x['rawUnchanged'] is True and x['semanticReadRanges']
  projection=d['sourceBindingsProjection'];assert len(d['sourceBindings'])==69
  assert d['sourceBindings']==[{k:x[k] for k in projection['fields']} for x in s['records']]
  assert {x['path'] for x in d['outputBindings']}=={(folder/n).as_posix() for n in ['report.md','sources.json']}
  for x in d['outputBindings']:assert binding(x['path'])==x
  projections=s['projections']
  for x in projections:
   val=original(x['source'],x['pointer']);fields=x['fields']
   if fields is None or fields==['*']:expected=val
   else:
    assert isinstance(fields,list) and len(fields)==len(set(fields))
    expected={k:(ptr(val,'/'+k) if '/' in k else val[k]) for k in fields}
   assert x['originalValue']==expected,(role,x['source'],x['pointer'],fields)
  count_expected=192 if role=='didaktik' else 230;assert len(projections)==count_expected
  for c in inp['selectedCases']:
   for k in ['input','scene','oracle']:
    assert any(x['source']==c[k]['path'] for x in projections)
  assert len(s['mutableParentContexts'])==3 and {x['path'] for x in s['mutableParentContexts']}==set(mutable)
  transitions=changed=0
  for c in s['mutableParentContexts']:
   assert bind3(c['frozenBase'])==bind3(mutable[c['path']]) and c['frozenBase']['utf8Raw']==mutable[c['path']]['utf8Raw']
   snapshots={k:v for k,v in c.items() if isinstance(v,dict) and 'utf8Raw' in v}
   for key,x in snapshots.items():
    raw=verify_raw(x)
    if 'commit' in x:assert git('show',x['commit']+':'+Path(c['path']).relative_to(REPO).as_posix())==raw
   assert verify_raw(c['after'])==Path(c['path']).read_bytes()
   for t in c['transitions']:
    before=verify_raw(c[t['from']]);after=verify_raw(c[t['to']])
    if role=='didaktik':
     a=before.decode('utf-8');b=after.decode('utf-8');n=t['prefixCharacters'];m=t['suffixCharacters']
     assert t['unit']=='unicode_characters_preserving_exact_utf8'
     assert a[n:len(a)-m if m else len(a)]==t['removedUtf8Raw']
     restored=(a[:n]+t['insertedUtf8Raw']+(a[-m:] if m else '')).encode('utf-8')
     assert t['fromSha256']==digest(before) and t['toSha256']==digest(after)
    else:
     n=t['prefixBytes'];m=t['suffixBytes'];removed=base64.b64decode(t['removedBase64'],validate=True);inserted=base64.b64decode(t['insertedBase64'],validate=True)
     assert before[n:len(before)-m if m else len(before)]==removed
     restored=before[:n]+inserted+(before[-m:] if m else b'')
     assert t['beforeSha256']==digest(before) and t['afterSha256']==digest(after)
    assert restored==after and t['reconstructionVerified'] is True and t['changed']==(before!=after)
    transitions+=1;changed+=int(before!=after)
  assert d['parentWriteScopeCheck']==s['parentWriteScopeCheck'];pc=d['parentWriteScopeCheck']
  if role=='didaktik':
   assert pc['parentBase']==inp['parentBase'] and pc['afterHead']==BASE and pc['outOfAllowedSet']==[]
   assert set(pc['observedPathUnion'])==set(commit_paths) and pc['onlyAllowedParentPaths'] is True
   assert pc['otherListedContentsRead'] is False and pc['ownRepositoryWrites'] is False
   assert d['reviewBoundary']['proceduralOriginalDiagnosticRequirement']=='NOT_FULLY_SATISFIED'
   assert any(x['id']=='DID-GP01-F02' and x['severity']=='HIGH' for x in d['findings'])
   primary_gap=[x['id'] for x in s['incidents'] if x.get('originalDiagnosticsAvailable') is False]
   assert len(primary_gap)==5
  else:
   assert pc['base']==inp['parentBase'] and pc['headAfter']==BASE and pc['unallowedAfter']==[]
   assert set(pc['actualObservedPathUnion'])==set(commit_paths)
   assert pc['otherListedPathContentsRead'] is False and pc['ownRepositoryWrites'] is False
   failures=[x for x in s['incidents'] if 'exitCode' in x];assert len(failures)==7
   for x in failures:
    assert x['exitCode'] in [1,2] and x['originalOutput'] and x['requestedPythonCode']
    assert digest(x['requestedPythonCode'].encode())==x['requestedPythonCodeSha256']
    assert digest(x['originalOutput'].encode())==x['originalOutputSha256']
   assert digest(s['documentReaderCode'].encode())==s['documentReaderCodeSha256']
  words=len((folder/'report.md').read_bytes().decode().split());assert 0<words<=1600
  result.append({'role':role,'outputs':files,'declaredScopeStatus':d['scopeStatus'],'declaredVote':d['wholeTextVote'],'unconditional':True,'sectionCount':7,'fixedBindings':69,'originalProjections':len(projections),'mutableTransitions':transitions,'changedTransitions':changed,'reportWhitespaceWords':words,'incidentsRetained':len(s['incidents']),'wholeProcedurePassed':False,'countedVote':role=='architekt','parentDisposition':'COMPLETE_TEXT_VOTE_WITH_RETAINED_EXCEPTIONS' if role=='architekt' else 'NOT_COUNTED_INCOMPLETE_PROCEDURAL_EVIDENCE_FRESH_REVIEW_REQUIRED','evidenceGapIds':primary_gap if role=='didaktik' else [],'qualification':'Stored source/code/output bindings checked; this is not independent execution authentication or a product test.'})
 return {'status':'PASS_RETURN_BINDINGS_WITH_DIDACTIC_COUNTABILITY_BLOCK','at':datetime.datetime.now().astimezone().isoformat(),'base':BASE,'batch':'deleg_8ca1aeb1','helper':binding(__file__),'freeze':[binding(ROOT/n) for n in FREEZE_PINS],'subject':inp['proposal'],'roles':result,'countedWholeTextVotes':sum(x['countedVote'] for x in result),'countedRoles':[x['role'] for x in result if x['countedVote']],'pendingRoles':['didaktik','redteam'],'parentPathCount':len(commit_paths),'parentIncidents':[binding(OUT/n) for n in ['inspection-output-qualification.json','inspection-incident-01.json']],'wholeReadSetUnchanged':False,'wholeProcedurePassed':False,'recommendationsAccepted':False,'ratificationIssued':False,'implementationAuthorized':False,'blockerClosed':False,'wholeManifestVerdict':'NOT_ISSUED','productParserSchemaEvaluatorTestsNative':'NOT_RUN','semanticExecutionPerformed':False}
